import { quoteBooking } from '/tmp/eval-work-jUt4V3/quote_booking.ts';

// Reference implementation of the ORIGINAL logic
function discount(ly:number, coupon?:string){ return coupon==='VIP' || ly>=3; }
function policy(ly:number, coupon?:string){ return coupon==='VIP' || ly>2; }
function orig(raw:any){
  if(typeof raw!=="object"||raw===null) return {ok:false,error:"malformed request"};
  const req=raw as any;
  if(!Number.isInteger(req.loyaltyYears)||req.loyaltyYears<0) return {ok:false,error:"bad loyalty"};
  const specs:any={
    standard:{maxN:14,maxG:2,base:80,high:30,flat:0,surch:0,minStay:0},
    suite:{maxN:21,maxG:4,base:150,high:60,flat:0,surch:25,minStay:0},
    villa:{maxN:28,maxG:8,base:300,high:120,flat:500,surch:0,minStay:3},
  };
  const s=specs[req.category];
  if(!s) return {ok:false,error:"unknown category"};
  const n=req.nights,g=req.guests,se=req.season,ly=req.loyaltyYears,c=req.coupon;
  if(!Number.isInteger(n)||n<1||n>s.maxN) return {ok:false,error:"bad nights"};
  if(n<s.minStay) return {ok:false,error:"villa minimum stay"};
  if(!Number.isInteger(g)||g<1||g>s.maxG) return {ok:false,error:"bad guests"};
  if(se!=="low"&&se!=="high") return {ok:false,error:"bad season"};
  let total=(s.base+(se==="high"?s.high:0))*n;
  if(discount(ly,c)) total-=Math.floor(total/10);
  if(g>2) total+=s.surch;
  total+=s.flat;
  const pol=policy(ly,c)?"flex":"strict";
  return {ok:true,total,policy:pol,line:req.category+":"+n+"n:"+total+":"+pol};
}

let diffs=0;
const cats=["standard","suite","villa","mansion",undefined];
const lys=[-1,0,1,2,3,4,1.5,"3"];
const nights=[0,1,2,3,5,14,15,21,22,28,29];
const guests=[-1,0,1,2,3,4,5,8,9];
const seasons=["low","high","peak",undefined];
const coupons=[undefined,"VIP","X",null];
for(const cat of cats) for(const ly of lys) for(const n of nights) for(const g of guests) for(const se of seasons) for(const c of coupons){
  const raw:any={category:cat,loyaltyYears:ly,nights:n,guests:g,season:se}; if(c!==undefined) raw.coupon=c;
  const a=quoteBooking(raw), b=orig(raw);
  if(JSON.stringify(a)!==JSON.stringify(b)){ if(diffs++<20) console.log("DIFF",raw, a,b); }
}
for(const raw of [null, 5, undefined, "x", {}]){
  const a=quoteBooking(raw), b=orig(raw);
  if(JSON.stringify(a)!==JSON.stringify(b)){ console.log("TOP DIFF",raw,a,b); diffs++; }
}
console.log("total diffs:", diffs);
