export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  maxNights: number;
  minStay?: number;
  maxGuests: number;
  base: number;
  high: number;
  guestSurcharge?: number;
  flat?: number;
}

const CATEGORIES: Record<string, CategorySpec> = {
  standard: { maxNights: 14, maxGuests: 2, base: 80, high: 30 },
  suite: { maxNights: 21, maxGuests: 4, base: 150, high: 60, guestSurcharge: 25 },
  villa: { maxNights: 28, minStay: 3, maxGuests: 8, base: 300, high: 120, flat: 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const category = req.category as string;
  const spec = CATEGORIES[category];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minStay !== undefined && nights < spec.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  const season = req.season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = (spec.base + (season === "high" ? spec.high : 0)) * nights;
  if ((req.loyaltyYears as number) >= 3 || req.coupon === "VIP") {
    total -= Math.floor(total / 10);
  }
  if (spec.guestSurcharge !== undefined && guests > 2) {
    total += spec.guestSurcharge;
  }
  if (spec.flat !== undefined) {
    total += spec.flat;
  }

  const policy = req.coupon === "VIP" || (req.loyaltyYears as number) > 2 ? "flex" : "strict";
  const line = category + ":" + nights + "n:" + total + ":" + policy;
  return { ok: true, total, policy, line };
}

